// TS-10: Keine Bindungen, Kontexte, Schemata oder Credentials im Code.
// Grundlage ist ausschliesslich die Zeile aus jarvis_ops.source_binding und context_registry.
const e = $('Eingabe pruefen').first().json;
const zeilen = $input.all();
if (zeilen.length !== 1) {
  throw new Error("context_resolve_db_error: Bindungsabfrage lieferte " + zeilen.length + " Zeilen statt 1");
}
const b = zeilen[0].json;
let code = "";
let grund = "";
if (e.input_reason) { code = "input_invalid"; grund = e.input_reason; }
else if (b.found !== true) { code = "binding_unknown"; grund = "source_binding nicht registriert: " + e.source_binding; }
else if (b.enabled !== true) { code = "binding_disabled"; grund = "Bindung deaktiviert: " + e.source_binding; }
else if (b.context_status !== "active") { code = "context_not_active"; grund = "Kontext der Bindung nicht aktiv"; }
else if (b.halted === true) { code = "binding_halted"; grund = "Bindung angehalten: " + e.source_binding; }
else if (e.context_id_hint && e.context_id_hint !== b.context_id) { code = "hint_conflict"; grund = "context_id_hint widerspricht der Bindung"; }
const ok = code === "";
return [{ json: {
  resolved: ok,
  context_id: ok ? b.context_id : null,
  db_schema: ok ? b.db_schema : null,
  resolution_method: "source_binding",
  source_binding: e.source_binding,
  reason_code: code,
  reason: grund,
  trace_id: e.trace_id
} }];

const alle = $input.all();
if (alle.length !== 1) {
  throw new Error("context_resolve_invalid_input: genau ein Aufruf je Ausfuehrung erwartet, erhalten " + alle.length);
}
const e = alle[0].json;
const bindung = (e.source_binding === undefined || e.source_binding === null) ? "" : String(e.source_binding);
let grund = "";
if (!bindung) { grund = "source_binding fehlt"; }
else if (!/^[a-z][a-z0-9_]{2,63}$/.test(bindung)) { grund = "source_binding hat kein gueltiges Format"; }
return [{ json: {
  source_binding: grund ? null : bindung,
  lookup_key: grund ? "-" : bindung,
  context_id_hint: e.context_id_hint ? String(e.context_id_hint) : "",
  input_reason: grund,
  trace_id: e.trace_id || null
} }];
